     3	/// Decodes the bundled `Acknowledgements.json` legal-notice catalog.
     4	///
     5	/// Schema v1:
     6	/// - `schemaVersion`: integer schema marker.
     7	/// - `audit`: dependency-audit metadata with `packageResolvedOriginHash`,
     8	///   `auditedPackagePins`, `sourceFiles`, and `omissions`.
     9	/// - `sections`: localized UI groupings. Each section has `id`, `titleKey`, and `entries`.
    10	/// - `entries`: legal notices with `id`, `name`, `version`, `licenseName`,
    11	///   `copyright`, `url`, and verbatim `notice` text.
    12	///
    13	/// When `Package.resolved` changes, re-audit the source files listed in the JSON:
    14	/// the app `LICENSE.md`, `Package.resolved`, and each resolved non-Apple Swift Package
    15	/// license file under Xcode's `SourcePackages/checkouts`. During the planned Mapbox to
    16	/// MapLibre migration, replace the Mapbox package pins and Mapbox notice entries in the
    17	/// JSON with the MapLibre package metadata and notices, keeping this loader unchanged.
    18	struct AcknowledgementCatalog: Decodable {
    19	    let schemaVersion: Int
    20	    let audit: AcknowledgementAudit
    21	    let sections: [AcknowledgementSection]
    22	
    23	    static func load(
    24	        from bundle: Bundle = .main,
    25	        resourceName: String = "Acknowledgements"
    26	    ) throws -> AcknowledgementCatalog {
    27	        guard let url = bundle.url(forResource: resourceName, withExtension: "json") else {
    28	            throw LoadError.missingResource(resourceName: resourceName)
    29	        }
    30	
    31	        let data: Data
    32	        do {
    33	            data = try Data(contentsOf: url)
    34	        } catch {
    35	            throw LoadError.unreadableResource(resourceName: resourceName, underlying: error)
    36	        }
    37	
    38	        do {
    39	            return try JSONDecoder().decode(AcknowledgementCatalog.self, from: data)
    40	        } catch {
    41	            throw LoadError.malformedResource(resourceName: resourceName, underlying: error)
    42	        }
    43	    }
    44	
    45	    enum LoadError: LocalizedError {
    46	        case missingResource(resourceName: String)
    47	        case unreadableResource(resourceName: String, underlying: Error)
    48	        case malformedResource(resourceName: String, underlying: Error)
    49	
    50	        var errorDescription: String? {
    51	            switch self {
    52	            case .missingResource(let resourceName):
    53	                return "Missing bundled acknowledgement resource: \(resourceName).json"
    54	            case .unreadableResource(let resourceName, let underlying):
    55	                return "Could not read acknowledgement resource \(resourceName).json: \(underlying.localizedDescription)"
    56	            case .malformedResource(let resourceName, let underlying):
    57	                return "Could not decode acknowledgement resource \(resourceName).json: \(underlying.localizedDescription)"
    58	            }
    59	        }
    60	    }
    61	}
